package com.guardianxr.ar;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.security.*;import java.text.*;import java.util.*;
public class CertificateActivity extends Activity{
 public static String id(String module,long ts){try{String s="GXR|"+module+"|"+ts+"|SIH26041";byte[] d=MessageDigest.getInstance("SHA-256").digest(s.getBytes());StringBuilder b=new StringBuilder();for(int i=0;i<6;i++)b.append(String.format("%02X",d[i]));return "GXR-"+b;}catch(Exception e){return "GXR-"+ts;}}
 public void onCreate(Bundle b){super.onCreate(b);String m=getIntent().getStringExtra("module");if(m==null)m="FIRE";long ts=System.currentTimeMillis();String cid=id(m,ts),payload="GUARDIANXR|"+cid+"|"+m+"|PASSED|"+ts;getSharedPreferences("guardianxr",MODE_PRIVATE).edit().putString("cert_"+cid,payload).putString("last_cert",cid).apply();LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setGravity(Gravity.CENTER);l.setPadding(30,40,30,30);l.setBackgroundColor(0xff07101c);TextView h=new TextView(this);h.setText("GuardianXR\nSAFETY TRAINING CERTIFICATE\n\n"+m+" MODULE • PASSED\nCertificate ID: "+cid+"\n"+new SimpleDateFormat("dd MMM yyyy",Locale.US).format(new Date(ts))+"\n\nOffline-verifiable QR");h.setTextColor(Color.WHITE);h.setTextSize(19);h.setGravity(Gravity.CENTER);l.addView(h);ImageView q=new ImageView(this);q.setImageBitmap(QrUtil.make(payload,720));l.addView(q,new LinearLayout.LayoutParams(720,720));Button share=new Button(this);share.setText("Share certificate code");String finalCid=cid;share.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,"GuardianXR certificate: "+finalCid);startActivity(Intent.createChooser(i,"Share"));});l.addView(share);setContentView(l);}
}